const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
const N = data[0];
const M = data[1];

const den = new Int32Array(M);
for (let i = 0; i < M; i++) {
  den[i] = data[2 + i] - 1;
}

const out = [];

for (let k = 1; k <= 10000; k++) {
  let r = k;

  for (let i = M - 1; i >= 0; i--) {
    r += ((r - 1) / den[i]) | 0;
    if (r > N) break;
  }

  if (r <= N) {
    out.push(r);
  } else {
    break;
  }
}

process.stdout.write(out.join('\n'));
